CREATE OR REPLACE FUNCTION public.fn_apply_mystery_bounty_config(p_tournament_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_club uuid; v_stage text; v_is_mb boolean;
  v_activation text; v_profile text;
  v_value numeric; v_top numeric; v_mystery numeric; v_regular numeric;
BEGIN
  SELECT club_id, mystery_bounty_stage, is_mystery_bounty
    INTO v_club, v_stage, v_is_mb
    FROM public.tournaments WHERE id = p_tournament_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'tournament_not_found'); END IF;

  -- Only the people who could have created the event can configure it, and
  -- only before the chests exist: after activation these columns describe an
  -- inventory already built from them, and changing one would make the record
  -- of how the money was split a lie.
  IF v_uid IS NOT NULL AND NOT public.fn_can_create_games(v_club, v_uid)
     AND NOT public.is_club_admin(v_club, v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authorised');
  END IF;
  IF NOT COALESCE(v_is_mb, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_a_mystery_bounty');
  END IF;
  IF v_stage IS DISTINCT FROM 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'already_activated');
  END IF;

  v_activation := COALESCE(p_config->>'activation', 'at_the_money');
  IF v_activation NOT IN ('at_the_money','percent_field','player_count') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_activation_mode');
  END IF;
  v_profile := COALESCE(p_config->>'profile', 'classic');
  IF v_profile NOT IN ('balanced','classic','jackpot') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'bad_profile');
  END IF;

  v_value := (p_config->>'activationValue')::numeric;
  IF v_activation = 'percent_field' AND (COALESCE(v_value,0) <= 0 OR v_value > 100) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'activation_percent_out_of_range');
  END IF;
  IF v_activation = 'player_count' AND COALESCE(v_value,0) < 2 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'activation_count_too_small');
  END IF;

  v_top := COALESCE((p_config->>'topPercent')::numeric, 20);
  IF v_top <= 0 OR v_top > 100 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'top_percent_out_of_range');
  END IF;

  v_mystery := COALESCE((p_config->>'poolPercent')::numeric, 50);
  v_regular := COALESCE((p_config->>'regularPoolPercent')::numeric, 100 - v_mystery);
  IF v_mystery < 0 OR v_regular < 0 OR v_mystery + v_regular <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'pool_split_invalid');
  END IF;

  UPDATE public.tournaments
     SET mystery_bounty_activation = v_activation,
         mystery_bounty_activation_value = v_value,
         mystery_bounty_profile = v_profile,
         mystery_bounty_top_percent = v_top,
         mystery_bounty_pool_percent = v_mystery,
         mystery_bounty_regular_pool_percent = v_regular
   WHERE id = p_tournament_id;

  RETURN jsonb_build_object('ok', true, 'activation', v_activation, 'profile', v_profile,
    'activation_value', v_value, 'top_percent', v_top,
    'pool_percent', v_mystery, 'regular_pool_percent', v_regular);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_create_tournament(p_club_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_res jsonb;
  v_pct smallint;
  v_id  uuid;
  v_saved_pct smallint;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','not_authenticated');
  END IF;
  IF NOT public.fn_can_create_games(p_club_id,v_uid) THEN
    RETURN jsonb_build_object('success',false,'error','not_authorised');
  END IF;

  -- Preserve the existing 10% fallback for absent or invalid input. Only
  -- input decoding is recoverable: a failed contract write must roll back
  -- the delegated create in the same database transaction.
  BEGIN
    v_pct := CASE WHEN (p_config->>'payoutPercent')::int IN (10,15,20)
                  THEN (p_config->>'payoutPercent')::smallint ELSE 10 END;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    v_pct := 10;
  END;

  v_res := public.fn_create_tournament_governed_legacy(p_club_id,p_config);
  IF v_res->'success' = 'false'::jsonb THEN
    RETURN v_res;
  END IF;
  IF v_res->'success' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'Tournament creation returned an unconfirmed receipt';
  END IF;

  -- The governed creator returns tournament_id. A missing, malformed or
  -- cross-club receipt cannot be accepted as a successful creation.
  v_id := NULLIF(v_res->>'tournament_id','')::uuid;
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'Tournament creation returned no tournament_id';
  END IF;
  UPDATE public.tournaments SET payout_percent = v_pct
   WHERE id = v_id AND club_id = p_club_id
   RETURNING payout_percent INTO v_saved_pct;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament creation receipt does not identify its club event';
  END IF;

  IF v_saved_pct IS DISTINCT FROM v_pct THEN
    RAISE EXCEPTION 'Tournament payout depth was not persisted';
  END IF;

  RETURN v_res;
END $function$

CREATE OR REPLACE FUNCTION public.fn_guard_registered_tournament_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb;
  v_new jsonb;
BEGIN
  v_old := public.fn_managed_game_contract_document('tournament', to_jsonb(OLD));
  v_new := public.fn_managed_game_contract_document('tournament', to_jsonb(NEW));

  -- auth.uid() is present for an operator/browser request and null for the
  -- service-role tournament engine. The engine may execute deterministic
  -- lifecycle adaptations such as fitting a payout ladder to the final field;
  -- those changes are captured as a new system revision below. Operators can
  -- never use that exception because their JWT keeps auth.uid() populated.
  IF auth.uid() IS NOT NULL AND v_old IS DISTINCT FROM v_new AND EXISTS (
    SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'Tournament contract cannot be modified after a player has registered'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$
